// =====================================================================
// export.js — turn the world you built into files for your ROS project
//   scenario.json : neutral format (single source of truth)
//   world.yaml    : same content, human friendly (ROS parameter style)
//   road.xodr     : OpenDRIVE 1.6 road -> CARLA, RoadRunner, esmini, MATLAB
//   log.csv       : recorded run
//   *.zip         : everything in one package (stored, no compression)
// =====================================================================

// ---------- YAML (tiny serializer, enough for plain objects/arrays) ----------
export function toYAML(v, ind = '') {
  if (Array.isArray(v)) {
    if (!v.length) return ' []';
    return v.map(it => {
      if (it && typeof it === 'object') {
        const body = toYAML(it, ind + '  ').replace(/^\n/, '');
        return '\n' + ind + '- ' + body.trimStart();
      }
      return '\n' + ind + '- ' + scalar(it);
    }).join('');
  }
  if (v && typeof v === 'object') {
    return Object.entries(v).map(([k, x]) => {
      if (x && typeof x === 'object') return '\n' + ind + k + ':' + toYAML(x, ind + '  ');
      return '\n' + ind + k + ': ' + scalar(x);
    }).join('');
  }
  return ' ' + scalar(v);
}
function scalar(x) {
  if (typeof x === 'number') return Number.isInteger(x) ? String(x) : String(+x.toFixed(4));
  if (typeof x === 'boolean') return x ? 'true' : 'false';
  if (x == null) return 'null';
  const s = String(x);
  return /^[\w.\-/ ]+$/.test(s) && !/^(true|false|null|yes|no)$/i.test(s) && !/^[\d.\-]+$/.test(s) ? s : JSON.stringify(s);
}

// ---------- OpenDRIVE 1.6 ----------
// planView: one <geometry> per primitive (line / arc / spiral) with exact start pose.
// elevationProfile: one cubic per user segment (a=z0, b=0, c=3dz/L^2, d=-2dz/L^3).
// objects: bridges. signals: speed limits (Italian codes). Centre-line roadMark changes
// between solid and broken following the no-overtaking zones.
export function toXODR(road, name) {
  const c = road.cfg, w = c.laneWidth, f = (x) => (+x).toFixed(6);
  const geo = road.prims.map(g => {
    const body = g.type === 'line' ? '<line/>' : g.type === 'arc' ? `<arc curvature="${f(g.k0)}"/>` : `<spiral curvStart="${f(g.k0)}" curvEnd="${f(g.k1)}"/>`;
    return `      <geometry s="${f(g.s0)}" x="${f(g.x)}" y="${f(g.y)}" hdg="${f(g.hdg)}" length="${f(g.len)}">${body}</geometry>`;
  }).join('\n');
  const elev = road.segInfo.map(si => { const L = si.s1 - si.s0, dz = si.z1 - si.z0; return `      <elevation s="${f(si.s0)}" a="${f(si.z0)}" b="0" c="${f(3 * dz / (L * L))}" d="${f(-2 * dz / (L * L * L))}"/>`; }).join('\n');
  const marks = [];
  if (c.nLeft === 0) marks.push([0, 'solid']);
  else { let prev = null; for (let j = 0; j < road.solidArr.length; j++) { const t = road.solidArr[j] ? 'solid' : 'broken'; if (t !== prev) { marks.push([j * road.solidStep, t]); prev = t; } } }
  const rm = (t) => `<roadMark sOffset="0" type="${t}" weight="standard" color="standard" width="0.15" laneChange="${t === 'solid' ? 'none' : 'both'}"/>`;
  const lane = (id, outer) => `          <lane id="${id}" type="driving" level="false"><link/><width sOffset="0" a="${f(w)}" b="0" c="0" d="0"/>${rm(outer ? 'solid' : 'broken')}<speed sOffset="0" max="${c.speedLimit}" unit="km/h"/></lane>`;
  const left = []; for (let i = c.nLeft; i >= 1; i--) left.push(lane(i, i === c.nLeft));
  const right = []; for (let i = 1; i <= c.nRight; i++) right.push(lane(-i, i === c.nRight));
  const bridges = road.features.filter(x => x.type === 'bridge').map((b, i) => `      <bridge s="${f(b.s0)}" length="${f(b.s1 - b.s0)}" name="bridge_${i + 1}" id="b${i + 1}" type="concrete"/>`);
  const overs = road.features.filter(x => x.type === 'overpass').map((o, i) => `      <object type="bridge" name="overpass_${i + 1}" id="o${i + 1}" s="${f((o.s0 + o.s1) / 2)}" t="0" zOffset="5.9" length="11" width="${f(road.edgeLeft - road.edgeRight + 44)}" height="1.1" hdg="1.570796" orientation="none"/>`);
  let prevLim = null, sid = 0; const sigs = [];
  for (const si of road.segInfo) { const lim = si.g.limit > 0 ? si.g.limit : c.speedLimit; if (lim !== prevLim) sigs.push(`      <signal s="${f(si.s0 + 15)}" t="${f(road.edgeRight - 1.6)}" id="s${++sid}" name="speed_limit" dynamic="no" orientation="+" zOffset="1.8" country="IT" type="274" subtype="${lim}" value="${lim}" unit="km/h" height="0.9" width="0.9"/>`); prevLim = lim; }
  const link = road.closed ? `    <link>\n      <predecessor elementType="road" elementId="1" contactPoint="end"/>\n      <successor elementType="road" elementId="1" contactPoint="start"/>\n    </link>` : '    <link/>';
  return `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by WebDriveSim. Reference line = centre line between the two directions. -->
<OpenDRIVE>
  <header revMajor="1" revMinor="6" name="${name}" version="1.0" date="${new Date().toISOString()}" north="0" south="0" east="0" west="0">
    <geoReference><![CDATA[+proj=tmerc +lat_0=45.4642 +lon_0=9.19 +k=1 +x_0=0 +y_0=0 +ellps=WGS84 +units=m +no_defs]]></geoReference>
  </header>
  <road name="${name}" length="${f(road.length)}" id="1" junction="-1">
${link}
    <type s="0" type="${c.nLeft === 0 ? 'motorway' : 'rural'}"><speed max="${c.speedLimit}" unit="km/h"/></type>
    <planView>
${geo}
    </planView>
    <elevationProfile>
${elev}
    </elevationProfile>
    <lateralProfile/>
    <lanes>
      <laneSection s="0">
${c.nLeft ? '        <left>\n' + left.join('\n') + '\n        </left>\n' : ''}        <center>
          <lane id="0" type="none" level="false">
${marks.map(([s, t]) => `            <roadMark sOffset="${f(s)}" type="${t}" weight="standard" color="standard" width="0.15" laneChange="${t === 'solid' ? 'none' : 'both'}"/>`).join('\n')}
          </lane>
        </center>
        <right>
${right.join('\n')}
        </right>
      </laneSection>
    </lanes>
    <objects>
${[...bridges, ...overs].join('\n')}
    </objects>
    <signals>
${sigs.join('\n')}
    </signals>
  </road>
</OpenDRIVE>
`;
}

// ---------- CSV ----------
export function toCSV(rows) {
  if (!rows.length) return 'empty\n';
  const keys = Object.keys(rows[0]);
  return keys.join(',') + '\n' + rows.map(r => keys.map(k => {
    const v = r[k]; return typeof v === 'number' ? (+v.toFixed(4)) : (v ?? '');
  }).join(',')).join('\n') + '\n';
}

// ---------- ZIP (store method). Format: local headers + central directory ----------
const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
function crc32(b) { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 255] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; }
export function makeZip(files) {
  const enc = new TextEncoder(), parts = [], central = [];
  let off = 0;
  for (const f of files) {
    const name = enc.encode(f.name), data = enc.encode(f.text), crc = crc32(data);
    const h = new DataView(new ArrayBuffer(30));
    h.setUint32(0, 0x04034b50, true); h.setUint16(4, 20, true); h.setUint16(8, 0, true);
    h.setUint32(14, crc, true); h.setUint32(18, data.length, true); h.setUint32(22, data.length, true);
    h.setUint16(26, name.length, true);
    parts.push(new Uint8Array(h.buffer), name, data);
    const c = new DataView(new ArrayBuffer(46));
    c.setUint32(0, 0x02014b50, true); c.setUint16(4, 20, true); c.setUint16(6, 20, true);
    c.setUint32(16, crc, true); c.setUint32(20, data.length, true); c.setUint32(24, data.length, true);
    c.setUint16(28, name.length, true); c.setUint32(42, off, true);
    central.push(new Uint8Array(c.buffer), name);
    off += 30 + name.length + data.length;
  }
  const csize = central.reduce((a, b) => a + b.length, 0);
  const e = new DataView(new ArrayBuffer(22));
  e.setUint32(0, 0x06054b50, true); e.setUint16(8, files.length, true); e.setUint16(10, files.length, true);
  e.setUint32(12, csize, true); e.setUint32(16, off, true);
  const all = [...parts, ...central, new Uint8Array(e.buffer)];
  const out = new Uint8Array(all.reduce((a, b) => a + b.length, 0));
  let p = 0; for (const a of all) { out.set(a, p); p += a.length; }
  return out;
}

// README placed in the package
export function readme(name) {
  return `# ${name} — WebDriveSim world package

## Use it with the ROS 2 workspace
1. Copy \`${name}.json\` into the \`worlds/\` folder of the WebDriveSim repository (no rebuild needed).
2. Start: \`ros2 launch webdrivesim_bringup sim.launch.py world:=${name}.json\`
3. Open http://localhost:8080 (the page loads the world automatically).

## Files
- ${name}.json : the scenario (vehicle, sensor mounts and noise, road segments, lanes, traffic). Load it in WebDriveSim with "Load".
- world.yaml   : the same in YAML (readable from your nodes with PyYAML).
- road.xodr    : OpenDRIVE 1.6 road (planView with clothoids, elevation, bridges, speed-limit signals).
                 CARLA: client.generate_opendrive_world(open('road.xodr').read())
                 MATLAB: roadNetwork(scenario,'OpenDRIVE','road.xodr')   esmini: esmini --odr road.xodr --window 60 60 800 400

## Conventions
- Vehicle frame base_link / ego_vehicle: x forward, y left, z up (REP-103). Sensor mounts in this frame, yaw in degrees.
- Road (Frenet): s along the centre line, d lateral, positive LEFT. Your lanes are on the right (d < 0).
- Lane numbering in the JSON: 1 = lane next to the centre line (fast / overtaking lane), nRight = rightmost lane; negative = oncoming lanes.
- Units: SI unless the key says otherwise (_kmh, _deg).
`;
}

// ---------- scenario file (what goes into worlds/<name>.json) ----------
export function scenarioObject(cfg, road, sim, name, extras) {
  const b = extras.BLUEPRINTS[cfg.vehicle.bp], c = cfg.road;
  return {
    format: 'webdrivesim_scenario', version: 2, name, created: new Date().toISOString(),
    vehicle: { blueprint: cfg.vehicle.bp, name: b.name, paint: cfg.vehicle.color, model: 'kinematic_bicycle',
      dimensions_m: { length: b.L, width: b.W, height: b.H, wheelbase: b.wb, track: b.track }, mass_kg: b.m, cog_height_m: b.hcg, lf_m: b.lf, lr_m: +(b.wb - b.lf).toFixed(3),
      max_accel_mps2: b.aMax, max_decel_mps2: b.bMax, max_steer_rad: b.steerMax, actuators: { steer_tau_s: 0.12, steer_rate_rad_s: 0.7, accel_tau_s: 0.35 } },
    sensors: cfg.sensors.filter(s => s.enabled).map(s => {
      const L = extras.SENSOR_LIB[s.id], o = { id: s.id, type: L.kind, frame_id: 'ego_vehicle/' + s.id, topic: '/carla/ego_vehicle/' + s.id, rate_hz: L.rate, x: s.x, y: s.y, z: s.z, yaw_deg: s.yaw };
      if (['radar', 'camera', 'lidar'].includes(L.kind)) Object.assign(o, { range_m: s.range, hfov_deg: s.fov, noise_sigma: { range_m: s.sr, azimuth_deg: s.sa, range_rate_mps: s.sv } });
      if (L.kind === 'gnss') o.noise_sigma = { position_m: s.sxy };
      if (L.kind === 'imu') o.noise_sigma = { accel_mps2: s.sacc, yaw_rate_rad_s: s.sgyr };
      return o;
    }),
    noise_level: cfg.noise,
    road: { length_m: +road.length.toFixed(2), closed: road.closed, lanes: { our_direction: c.nRight, oncoming: c.nLeft, width_m: c.laneWidth }, speed_limit_kmh: c.speedLimit,
      center_line: c.centerLine, surface: c.wet ? 'wet' : 'dry', opendrive: 'road.xodr',
      segments: c.segments, features: road.features.map(f => ({ type: f.type, s_start_m: +f.s0.toFixed(1), s_end_m: +f.s1.toFixed(1) })) },
    environment: cfg.env,
    ego_start: { lane: road.laneName(cfg.ego.lane), lane_index: cfg.ego.lane, s_m: cfg.ego.s, speed_kmh: cfg.ego.speed },
    traffic: { seed: cfg.traffic.seed, model: cfg.traffic.behaviour === 'idm' ? 'IDM' : 'constant_speed',
      vehicles: sim.traffic.map(t => ({ id: t.id, type: t.bpKey, direction: t.dir > 0 ? 'same' : 'oncoming', lane: road.laneName(t.lane), lane_index: t.lane, s_m: +t.s.toFixed(1), speed_kmh: +(t.v0 * 3.6).toFixed(1), behaviour: t.behaviour })) },
    editor_state: cfg,
  };
}
